From f612cd729176e406071671f379514454036b9457 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 13:54:33 +0100
Subject: [PATCH] applets/kickoff: focus the search field when opening

Compose keys and input methods only work in a focused text field, so the
first accented letter typed after opening Kickoff lost its accent. The
field now gets focus and passes navigation keys to the view first.

BUG: 459269
---
 applets/kickoff/Header.qml          | 22 +++++++++++++++++++++-
 applets/kickoff/KickoffGridView.qml |  8 ++++----
 2 files changed, 25 insertions(+), 5 deletions(-)

diff --git a/applets/kickoff/Header.qml b/applets/kickoff/Header.qml
index 300654df9e..353005c9b3 100644
--- a/applets/kickoff/Header.qml
+++ b/applets/kickoff/Header.qml
@@ -191,6 +191,10 @@ PlasmaExtras.PlasmoidHeading {
                     Layout.leftMargin: kickoff.backgroundMetrics.leftPadding
                     focus: true

+                    // Focused by opening Kickoff: navigation keys still act on the
+                    // content area until the user types or moves focus elsewhere
+                    property bool focusedOnOpen: false
+
                     Binding {
                         target: kickoff
                         property: "searchField"
@@ -203,13 +207,24 @@ PlasmaExtras.PlasmoidHeading {
                         function onExpandedChanged() {
                             if (!kickoff.expanded) {
                                 searchField.clear()
+                            } else {
+                                // Input methods and compose/dead keys only work in a focused text field
+                                searchField.forceActiveFocus(Qt.OtherFocusReason)
+                                searchField.focusedOnOpen = true
                             }
                         }
                     }
+                    onActiveFocusChanged: {
+                        if (!activeFocus) {
+                            focusedOnOpen = false
+                        }
+                    }
+                    onPressed: focusedOnOpen = false
                     onTextEdited: {
+                        focusedOnOpen = false
                         searchField.forceActiveFocus(Qt.ShortcutFocusReason)
                     }
-                    Keys.priority: Keys.AfterItem
+                    Keys.priority: focusedOnOpen ? Keys.BeforeItem : Keys.AfterItem
                     Keys.forwardTo: {
                         if (kickoff.contentArea === null) {
                             return []
@@ -220,6 +235,11 @@ PlasmaExtras.PlasmoidHeading {
                         }
                         return kickoff.contentArea.view
                     }
+                    // Up from the top of the content area would focus the search field
+                    Keys.onUpPressed: event => {
+                        focusedOnOpen = false
+                        event.accepted = false
+                    }

                     Keys.onTabPressed: event => {
                         tabSetFocus(event, nextItemInFocusChain(false));
diff --git a/applets/kickoff/KickoffGridView.qml b/applets/kickoff/KickoffGridView.qml
index eab0c358b1..0e37ef17cc 100644
--- a/applets/kickoff/KickoffGridView.qml
+++ b/applets/kickoff/KickoffGridView.qml
@@ -238,11 +238,11 @@ EmptyPage {
                 event.accepted = true;
             } else if (count > 1) {
                 switch (event.key) {
-                    case Qt.Key_Left: if (!atLeft && !kickoff.searchField.activeFocus) {
+                    case Qt.Key_Left: if (!atLeft && (!kickoff.searchField.activeFocus || kickoff.searchField.focusedOnOpen)) {
                         moveCurrentIndexLeft()
                         focusCurrentItem(event, Qt.BacktabFocusReason)
                     } break
-                    case Qt.Key_H: if (!atLeft && !kickoff.searchField.activeFocus && event.modifiers & Qt.ControlModifier) {
+                    case Qt.Key_H: if (!atLeft && (!kickoff.searchField.activeFocus || kickoff.searchField.focusedOnOpen) && event.modifiers & Qt.ControlModifier) {
                         moveCurrentIndexLeft()
                         focusCurrentItem(event, Qt.BacktabFocusReason)
                     } break
@@ -254,11 +254,11 @@ EmptyPage {
                         moveCurrentIndexUp()
                         focusCurrentItem(event, Qt.BacktabFocusReason)
                     } break
-                    case Qt.Key_Right: if (!atRight && !kickoff.searchField.activeFocus) {
+                    case Qt.Key_Right: if (!atRight && (!kickoff.searchField.activeFocus || kickoff.searchField.focusedOnOpen)) {
                         moveCurrentIndexRight()
                         focusCurrentItem(event, Qt.TabFocusReason)
                     } break
-                    case Qt.Key_L: if (!atRight && !kickoff.searchField.activeFocus && event.modifiers & Qt.ControlModifier) {
+                    case Qt.Key_L: if (!atRight && (!kickoff.searchField.activeFocus || kickoff.searchField.focusedOnOpen) && event.modifiers & Qt.ControlModifier) {
                         moveCurrentIndexRight()
                         focusCurrentItem(event, Qt.TabFocusReason)
                     } break
